class InterbotixMoveItInterface
{
public:
  /// @brief Constructor for the InterbotixMoveItInterface
  /// @param node SharedPtr to ROS2 node
  explicit InterbotixMoveItInterface(rclcpp::Node::SharedPtr & node);

